body:
### 功能改进

以下为 `noco` 无代码增删改查草案，欢迎各路好汉给出完善建议！

# 创建

```json
{
  "action": "create",
  "table": "users",
  "data": {
    "name": "hi",
    "email": "hi@example.com"
  }
}
```


# 读取

```json
{
  "action": "read",
  "table": "users",
  "query": {
    "id": { "$eq": 1 }
  }
}
```

# 更新

```json
{
  "action": "update",
  "table": "users",
  "query": {
    "id": { "$eq": 1 }
  },
  "data": {
    "email": "hi@example.com"
  }
}
```


# 删除

```json
{
  "action": "delete",
  "table": "users",
  "query": {
    "id": { "$eq": 1 }
  }
}
```

# 复杂联合查询

> join.type 连接类型 inner, left, right, full

```json
{
  "action": "read",
  "tables": ["users:u", "orders", "products"],
  "join": [
    {
      "type": "inner",
      "on": {
        "u.id": "orders.user_id"
      }
    },
    {
      "type": "left",
      "on": {
        "orders.product_id": "products.id"
      }
    }
  ],
  "select": [
    "u.name:userName",
    "u.email",
    "orders.order_id",
    "orders.total_amount",
    "products.product_name"
  ],
  "query": {
    "u.id":  { "$eq": 1 },
    "orders.total_amount": { "$gt": 100 }
  },
  "page": {
    "current": 1,
    "size": 10
  },
  "sorts": [
    "u.name",
    "orders.create_time:asc"
  ]
}
```

# 身份验证

```json
{
  "roles": [
    {
      "role": "admin",
      "permissions": ["create", "read", "update", "delete"]
    },
    {
      "role": "user",
      "permissions": ["read"]
    }
  ]
}
```


