	@Override
	public List<Float> getNullableResult(ResultSet rs, String columnName) throws SQLException {
		List<Float> list = new ArrayList<Float>();
		LocalDateTime frameDateTime = LocalDateTime.parse(rs.getString("CheckTime").replace(" ", "T"));
		String yyyymm = frameDateTime.format(DateTimeFormatter.ofPattern("yyyyMM"));
		String day = String.format("%02d", frameDateTime.getDayOfMonth());
		LocalTime frameTime = LocalTime.parse(rs.getString("CheckTime"),
				DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss"));
		File file = new File(rootLocation + "设备数据" + File.separator + yyyymm + File.separator + day);
		if (file.exists()) {
			String[] dailyPaths = file.list();
			ArrayList<LocalTime> times = new ArrayList<LocalTime>();
			for (String pathItem : dailyPaths) {
				times.add(LocalTime.parse(pathItem, DateTimeFormatter.ofPattern("HHmmss")));
			}
			times.sort((prev, next) -> prev.compareTo(next));
			log.debug(times.toString());
			String dailyPath = "";
			for (int i = 0; i < dailyPaths.length - 1; i++) {

				if (frameTime.compareTo(times.get(0)) == -1) {
					log.debug("成功为首期数据匹配到首部文件夹：" + dailyPaths[0]);
					dailyPath = dailyPaths[0];
					break;
				}
				if (frameTime.compareTo(times.get(times.size() - 1)) == 1) {
					log.debug("成功为末期数据匹配到末尾文件夹：" + dailyPaths[dailyPaths.length - 1]);
					dailyPath = dailyPaths[dailyPaths.length - 1];
					break;
				}

				// -1表示早于，1表示晚于，0则相等
				if (frameTime.compareTo(times.get(i + 1)) == 1) {
					log.debug("帧数据时间大于目标匹配文件夹后一个时间--跳过本轮比对");
					log.debug("帧数据时间：" + frameTime.toString());
					log.debug("目标文件夹后一个文件夹：" + times.get(i + 1));
					continue;
				}
				if (frameTime.compareTo(times.get(i)) >= 0 && frameTime.compareTo(times.get(i + 1)) == -1) {
					log.debug("成功匹配到目标文件夹：" + dailyPaths[i]);
					dailyPath = dailyPaths[i];
					break;
				}
				log.debug("未匹配到日详细信息文件夹，帧数据时间为：" + frameTime.toString() + "目标文件夹为：" + dailyPaths[i] + "目标后一个文件夹为："
						+ dailyPaths[i + 1] + "");
			}
			File csvFile = null;
			if (columnName.equals("VisOut")) {
				csvFile = new File(rootLocation + "设备数据" + File.separator + yyyymm + File.separator + day
						+ File.separator + dailyPath + File.separator + "能见度反演.csv");
			} else if (columnName.equals("Profile")) {
				csvFile = new File(rootLocation + "设备数据" + File.separator + yyyymm + File.separator + day
						+ File.separator + dailyPath + File.separator + "原始信号.csv");
			}
			log.debug(csvFile.getAbsolutePath());
			if (csvFile != null && csvFile.exists()) {
				log.debug("目标文件存在");
				return readDatFromDataFile(csvFile,
						frameDateTime.format(DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss")));
			}
			log.debug("日期文件夹存在");
		}
		return list;
	}

