	public ArrayList<Float> readDatFromDataFile(File tempFile, String dtStr) {
		if (!tempFile.exists()) {
			log.error("数据文件不存在不存", tempFile.getAbsolutePath());
			return null;
		}
		Reader in;
		try {
			in = new FileReader(tempFile);
			CSVParser parse = CSVFormat.EXCEL.parse(in);
			List<CSVRecord> records = parse.getRecords();
			if (records.size() < 2) {
				return null;
			}
			Optional<CSVRecord> matchRecord = records.stream().filter(item -> item.get(0).equals(dtStr)).findFirst();
			CSVRecord csvRecord = matchRecord.get();
			String string = csvRecord.get(3);
			String[] split = string.split(";");
			ArrayList<Float> finalFloats = new ArrayList<Float>();
			for (String str : split) {
				finalFloats.add(Float.parseFloat(str));
			}
			log.debug("CSV数据提取成功");
			return finalFloats;
		} catch (IOException e) {
			log.error("读取设备csv数据帧时发生异常");
			e.printStackTrace();
		}
		return null;
	}

}
