    /**
     * 分批插入
     *
     * @param modelCollection 数据集
     * @param size 分批大小
     * @return 影响行数
     */
    default int insertBatch(Collection<MODEL> modelCollection, int size) {
        return CollUtil.split(modelCollection, size).stream().mapToInt(c -> {
            insertBatchSomeColumn(c);
            return c.size();
        }).sum();
    }

    /**
