        //构建mybatis-plus需要的globalconfig
        GlobalConfig globalConfig = new GlobalConfig();
        //此参数会自动生成实现baseMapper的基础方法映射
        globalConfig.setSqlInjector(new CustomerSqlInjector());
        //设置超类mapper
        globalConfig.setSuperMapperClass(BaseMapper.class);
        configuration.setGlobalConfig(globalConfig);
        //设置数据源
        Environment environment = new Environment("1", new JdbcTransactionFactory(), initDataSource());
        configuration.setEnvironment(environment);
        //构建sqlSessionFactory
        return builder.build(configuration);
    }


    public static DataSource initDataSource() {
        HikariDataSource dataSource = new HikariDataSource();
        MysqlCluster mysqlCluster = new MysqlCluster();
        dataSource.setJdbcUrl(mysqlCluster.getParam(MysqlCluster.KEY_MYSQL_URL));
        dataSource.setDriverClassName("com.mysql.cj.jdbc.Driver");
        dataSource.setUsername(mysqlCluster.getParam(MysqlCluster.KEY_MYSQL_USERNAME));
        dataSource.setPassword(mysqlCluster.getParam(MysqlCluster.KEY_MYSQL_PASSWORD));
        dataSource.setIdleTimeout(30000);
        dataSource.setAutoCommit(true);
        dataSource.setConnectionTimeout(30000);
        dataSource.setValidationTimeout(3000);
        dataSource.setMaximumPoolSize(50);
        dataSource.setMinimumIdle(10);
        dataSource.setMaxLifetime(1800000);
        dataSource.setConnectionTestQuery("SELECT 1");
        return dataSource;
    }
}
