```java
package com.ruoyi.common.redis.configure;

import com.ruoyi.common.core.utils.SpringUtils;
import lombok.extern.slf4j.Slf4j;
import org.apache.ibatis.cache.Cache;
import org.springframework.data.redis.core.RedisTemplate;
import org.springframework.util.Assert;

import java.util.concurrent.locks.ReadWriteLock;
import java.util.concurrent.locks.ReentrantReadWriteLock;

/**
 * MyBatis Redis 缓存配置类
 */
@Slf4j
public class MyBatisRedisCache implements Cache {

    /**
     * 读写锁
     */
    private final ReadWriteLock readWriteLock = new ReentrantReadWriteLock(true);

    /**
     * ID，获取缓存对象的唯一标识
     */
    private String id;

    private static volatile RedisTemplate redisTemplate;

    public RedisTemplate getRedisTemplate() {
        if (redisTemplate == null) {
            synchronized (MyBatisRedisCache.class) {
                if (redisTemplate == null) {
                    redisTemplate = SpringUtils.getBean("redisTemplate");
                }
            }
        }
        return redisTemplate;
    }

    public MyBatisRedisCache(String id) {
        Assert.notNull(id, "RedisCache id 不能为空");
        log.info("Redis Cache 开启缓存, id: {}", id);
        this.id = id;
    }

    @Override
    public ReadWriteLock getReadWriteLock() {
        return this.readWriteLock;
    }

    @Override
    public String getId() {
        return this.id;
    }

    @Override
    public void putObject(Object key, Object value) {
        this.getRedisTemplate().opsForHash().put(this.id, key.toString(), value.toString());
    }

    @Override
    public Object getObject(Object key) {
        return this.getRedisTemplate().opsForHash().get(this.id, key.toString());
    }

    @Override
    public Object removeObject(Object key) {
        return getRedisTemplate().opsForHash().delete(this.id, key.toString());
    }

    @Override
    public void clear() {
        log.info("RedisCache clear, id: {}", id);
        getRedisTemplate().delete(this.id);
    }

    @Override
    public int getSize() {
        return getRedisTemplate().opsForHash().size(this.id).intValue();
    }
}

