            return invocation.proceed();
        } finally {
            logger.info("[包名] " + pName);
            logger.info("[删除前] " + DynamicDataSourceContextHolder.peek());
            DynamicDataSourceContextHolder.poll();
            logger.info("[删除后] " + DynamicDataSourceContextHolder.peek());
        }
    }
