    public int batchEditData(UpdateVo updateVo) {

        //拼接set字段sql
        List<ConditionVo> conditionVos = updateVo.getConditions();
        List<ScopeVo> scopeVos = updateVo.getScopes();
        if (conditionVos==null || conditionVos.size()==0){
            return 0;
        }
        if (scopeVos==null || scopeVos.size()==0){
            return 0;
        }

        UpdateWrapper updateWrapper = new UpdateWrapper();
        updateWrapper.set("upd_time",LocalDateTime.now());
        updateWrapper.set("upd_user_id",BaseContextHandler.getUserID());
        for (ConditionVo conditionVo : conditionVos) {
            if ("1".equals(conditionVo.getReplaceType())){ //全部替换
                updateWrapper.set(conditionVo.getName(),conditionVo.getReplaceValue());
            }else {
                //setSql = " name =relpale(name,'原值','新值') "
                String setSql = conditionVo.getName() + "= REPLACE("+ conditionVo.getName() + ",'"
                            + conditionVo.getOldValue() + "','" + conditionVo.getReplaceValue()+"') ";
                updateWrapper.setSql(setSql);
            }
        }
        //拼接where 条件sql
        QueryWrapper queryWrapper = new QueryWrapper();
        for (ScopeVo scopeVo : scopeVos) {
            if ("or".equalsIgnoreCase(scopeVo.getConnector())){
                queryWrapper.or();
            }
            if ("like".equalsIgnoreCase(scopeVo.getCondition())){
                queryWrapper.like(scopeVo.getName(),scopeVo.getContent());
            }else if (">".equals(scopeVo.getCondition())){
                queryWrapper.gt(scopeVo.getName(),scopeVo.getContent());
            }else if (">=".equals(scopeVo.getCondition())){
                queryWrapper.ge(scopeVo.getName(),scopeVo.getContent());
            }else if ("<".equals(scopeVo.getCondition())){
                queryWrapper.lt(scopeVo.getName(),scopeVo.getContent());
            }else if ("<=".equals(scopeVo.getCondition())){
                queryWrapper.le(scopeVo.getName(),scopeVo.getContent());
            }else if ("!=".equals(scopeVo.getCondition())){
                queryWrapper.ne(scopeVo.getName(),scopeVo.getContent());
            }else {
                queryWrapper.eq(scopeVo.getName(),scopeVo.getContent());
            }
        }

        TableBase base = tableBaseMapper.selectById(updateVo.getTableId());
        String tableEn = base.getTableEn();

        return dynamicMapper.batchModifyData(tableEn,updateWrapper,queryWrapper);
    }


